values
  ('00000000-0000-4000-8000-000000000001'::uuid, 'Maison Serein', 'Paris', 'France', 48.8654, 2.3339, 'Luxury', 395, ARRAY['fast_wifi','breakfast','spa','gym']::text[], ARRAY['romantic','boutique','design_led']::text[], 'A quiet side street near the Palais Royal. The intimate courtyard is lovely, but rooms are on the smaller side.', ARRAY['https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=1600&q=85','https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?w=1600&q=85','https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Paris%2C+France', 4.9, 428),
  ('00000000-0000-4000-8000-000000000002'::uuid, 'Atelier Saint-Michel', 'Paris', 'France', 48.8523, 2.3464, 'Mid-range', 178, ARRAY['fast_wifi','breakfast','workspace']::text[], ARRAY['boutique','remote_work','cultural']::text[], 'A walkable Left Bank base with a thoughtful breakfast. Street-facing rooms can pick up some evening noise.', ARRAY['https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?w=1600&q=85','https://images.unsplash.com/photo-1590490360182-c33d57733427?w=1600&q=85','https://images.unsplash.com/photo-1564501049412-61c2a3083791?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Paris%2C+France', 4.7, 612),
  ('00000000-0000-4000-8000-000000000003'::uuid, 'Le Petit Marais', 'Paris', 'France', 48.8575, 2.3601, 'Budget', 112, ARRAY['fast_wifi','breakfast']::text[], ARRAY['boutique','solo','cultural']::text[], 'Compact rooms put you close to the galleries and cafés of Le Marais. There is no on-site spa or pool.', ARRAY['https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1600&q=85','https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=1600&q=85','https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Paris%2C+France', 4.5, 903),
  ('00000000-0000-4000-8000-000000000004'::uuid, 'Kumo House Ginza', 'Tokyo', 'Japan', 35.6712, 139.7656, 'Luxury', 342, ARRAY['fast_wifi','breakfast','spa','gym']::text[], ARRAY['design_led','romantic','boutique']::text[], 'A hushed design retreat above Ginza''s bright streets. Dinner reservations are best made well ahead.', ARRAY['https://images.unsplash.com/photo-1584132967334-10e028bd69f7?w=1600&q=85','https://images.unsplash.com/photo-1540541338287-41700207dee6?w=1600&q=85','https://images.unsplash.com/photo-1590490360182-c33d57733427?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Tokyo%2C+Japan', 4.9, 511),
  ('00000000-0000-4000-8000-000000000005'::uuid, 'Nami Shibuya', 'Tokyo', 'Japan', 35.6609, 139.7006, 'Mid-range', 164, ARRAY['fast_wifi','breakfast','workspace','gym']::text[], ARRAY['remote_work','nightlife','design_led']::text[], 'A lively Shibuya base with useful workspaces. The neighborhood stays busy late into the night.', ARRAY['https://images.unsplash.com/photo-1564501049412-61c2a3083791?w=1600&q=85','https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1600&q=85','https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Tokyo%2C+Japan', 4.7, 784),
  ('00000000-0000-4000-8000-000000000006'::uuid, 'Asakusa Paper Lantern', 'Tokyo', 'Japan', 35.7144, 139.7967, 'Budget', 89, ARRAY['fast_wifi','breakfast','laundry']::text[], ARRAY['solo','cultural','quiet']::text[], 'An unfussy stay near the temples and riverside. Rooms are efficient in size, with limited storage.', ARRAY['https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=1600&q=85','https://images.unsplash.com/photo-1596436889106-be35e843f974?w=1600&q=85','https://images.unsplash.com/photo-1584132967334-10e028bd69f7?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Tokyo%2C+Japan', 4.6, 1042),
  ('00000000-0000-4000-8000-000000000007'::uuid, 'The Mercer Line', 'New York', 'United States', 40.7243, -73.9995, 'Luxury', 420, ARRAY['fast_wifi','gym','workspace','room_service']::text[], ARRAY['design_led','nightlife','remote_work']::text[], 'A polished SoHo address for restaurants and galleries. Expect the usual Manhattan street energy.', ARRAY['https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?w=1600&q=85','https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1600&q=85','https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=New+York%2C+United+States', 4.8, 692),
  ('00000000-0000-4000-8000-000000000008'::uuid, 'Broadway & Birch', 'New York', 'United States', 40.7477, -73.9881, 'Mid-range', 225, ARRAY['fast_wifi','breakfast','gym','family_rooms']::text[], ARRAY['family_friendly','cultural','remote_work']::text[], 'Central transit connections make sightseeing easy. Some rooms look over a busy avenue.', ARRAY['https://images.unsplash.com/photo-1564501049412-61c2a3083791?w=1600&q=85','https://images.unsplash.com/photo-1590490360182-c33d57733427?w=1600&q=85','https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=New+York%2C+United+States', 4.6, 931),
  ('00000000-0000-4000-8000-000000000009'::uuid, 'Canal Street Rooms', 'New York', 'United States', 40.7206, -73.9968, 'Budget', 139, ARRAY['fast_wifi','laundry']::text[], ARRAY['solo','nightlife','cultural']::text[], 'A simple downtown launchpad close to subway lines. Bathrooms and rooms are compact.', ARRAY['https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1600&q=85','https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=1600&q=85','https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=New+York%2C+United+States', 4.4, 1187),
  ('00000000-0000-4000-8000-000000000010'::uuid, 'Eko Palm House', 'Lagos', 'Nigeria', 6.4324, 3.4381, 'Luxury', 256, ARRAY['fast_wifi','pool','breakfast','gym','airport_transfer']::text[], ARRAY['romantic','design_led','business']::text[], 'A leafy Victoria Island retreat with a pool. Build extra time into cross-city trips when traffic is heavy.', ARRAY['https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=1600&q=85','https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1600&q=85','https://images.unsplash.com/photo-1584132967334-10e028bd69f7?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Lagos%2C+Nigeria', 4.8, 389),
  ('00000000-0000-4000-8000-000000000011'::uuid, 'Lekki Courtyard', 'Lagos', 'Nigeria', 6.4476, 3.4723, 'Mid-range', 138, ARRAY['fast_wifi','pool','breakfast','workspace','parking']::text[], ARRAY['remote_work','boutique','quiet']::text[], 'A calm courtyard and dependable work setup in Lekki. Plan for travel time when heading to the mainland.', ARRAY['https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1600&q=85','https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=1600&q=85','https://images.unsplash.com/photo-1540541338287-41700207dee6?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Lagos%2C+Nigeria', 4.7, 567),
  ('00000000-0000-4000-8000-000000000012'::uuid, 'Yaba Junction', 'Lagos', 'Nigeria', 6.5082, 3.3791, 'Budget', 72, ARRAY['fast_wifi','breakfast','parking']::text[], ARRAY['solo','remote_work','business']::text[], 'A practical base for meetings on the mainland. The setting favors convenience over resort amenities.', ARRAY['https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?w=1600&q=85','https://images.unsplash.com/photo-1590490360182-c33d57733427?w=1600&q=85','https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Lagos%2C+Nigeria', 4.5, 748),
  ('00000000-0000-4000-8000-000000000013'::uuid, 'The Ubud Canopy', 'Bali', 'Indonesia', -8.5041, 115.2641, 'Luxury', 310, ARRAY['fast_wifi','pool','spa','breakfast','yoga']::text[], ARRAY['wellness','romantic','quiet']::text[], 'A jungle-facing pool and restorative spa near Ubud. The hillside paths include steps.', ARRAY['https://images.unsplash.com/photo-1540541338287-41700207dee6?w=1600&q=85','https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=1600&q=85','https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Bali%2C+Indonesia', 4.9, 634),
  ('00000000-0000-4000-8000-000000000014'::uuid, 'Canggu Coast House', 'Bali', 'Indonesia', -8.6508, 115.1339, 'Mid-range', 148, ARRAY['fast_wifi','pool','breakfast','workspace']::text[], ARRAY['remote_work','beach','boutique']::text[], 'Walk to Canggu cafés and the beach from a relaxed poolside base. Nearby streets can be lively.', ARRAY['https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=1600&q=85','https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1600&q=85','https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Bali%2C+Indonesia', 4.8, 819),
  ('00000000-0000-4000-8000-000000000015'::uuid, 'Sanur Slow Days', 'Bali', 'Indonesia', -8.6961, 115.2654, 'Budget', 82, ARRAY['fast_wifi','pool','breakfast','family_rooms']::text[], ARRAY['family_friendly','beach','quiet']::text[], 'A slower beach neighborhood with a small pool. Transfers to the west coast take time.', ARRAY['https://images.unsplash.com/photo-1540541338287-41700207dee6?w=1600&q=85','https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=1600&q=85','https://images.unsplash.com/photo-1564501049412-61c2a3083791?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=Bali%2C+Indonesia', 4.6, 1051),
  ('00000000-0000-4000-8000-000000000016'::uuid, 'The Bloomsbury Fold', 'London', 'United Kingdom', 51.5192, -0.1255, 'Luxury', 365, ARRAY['fast_wifi','breakfast','spa','gym','room_service']::text[], ARRAY['romantic','boutique','cultural']::text[], 'Elegant rooms near museums and bookshops. Premium rooms have the most generous space.', ARRAY['https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?w=1600&q=85','https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1600&q=85','https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=London%2C+United+Kingdom', 4.9, 476),
  ('00000000-0000-4000-8000-000000000017'::uuid, 'Southbank Social', 'London', 'United Kingdom', 51.5037, -0.1079, 'Mid-range', 192, ARRAY['fast_wifi','breakfast','gym','family_rooms']::text[], ARRAY['family_friendly','cultural','design_led']::text[], 'A handy riverside base for first-time visitors. The restaurant is busiest around showtime.', ARRAY['https://images.unsplash.com/photo-1564501049412-61c2a3083791?w=1600&q=85','https://images.unsplash.com/photo-1590490360182-c33d57733427?w=1600&q=85','https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=London%2C+United+Kingdom', 4.7, 942),
  ('00000000-0000-4000-8000-000000000018'::uuid, 'Shoreditch Studio Stay', 'London', 'United Kingdom', 51.5256, -0.0785, 'Budget', 118, ARRAY['fast_wifi','workspace','laundry']::text[], ARRAY['solo','nightlife','remote_work']::text[], 'Good value near independent shops and late-night food. The rooms are compact and the area stays lively.', ARRAY['https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1600&q=85','https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=1600&q=85','https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?w=1600&q=85']::text[], 'https://www.booking.com/searchresults.html?ss=London%2C+United+Kingdom', 4.5, 1233)
