-- Generated from data/hotels.json by npm run seed:generate.
-- Fictional demo hotels: replace with licensed, verified properties before launch.
on conflict (id) do update set
  name = excluded.name,
  city = excluded.city,
  country = excluded.country,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  price_tier = excluded.price_tier,
  estimated_price_per_night = excluded.estimated_price_per_night,
  amenities = excluded.amenities,
  vibe_tags = excluded.vibe_tags,
  editorial_notes = excluded.editorial_notes,
  image_urls = excluded.image_urls,
  affiliate_booking_link = excluded.affiliate_booking_link,
  rating = excluded.rating,
  review_count = excluded.review_count;
